PREFIX wd: <http://www.wikidata.org/entity/>
PREFIX wdt: <http://www.wikidata.org/prop/direct/>
SELECT (YEAR(?date) AS ?year)
WHERE {
  ?superbowl wdt:P31 wd:Q815013 ;
            wdt:P47 wd:Q75075 ;
            wdt:P585 ?date .
}
ORDER BY DESC(?date)
LIMIT 1

